import{_ as t,a,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"网球规则 · 八、用三个场景把比分读完整至官方来源与复核入口","description":"网球单打与双打的场地、发球、局盘计分、抢七、抢十和常见判例","frontmatter":{"title":"网球规则 · 八、用三个场景把比分读完整至官方来源与复核入口","description":"网球单打与双打的场地、发球、局盘计分、抢七、抢十和常见判例","splitFrom":"life/personal/sports/tennis-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"网球规则","summary":"网球单打与双打的场地、发球、局盘计分、抢七、抢十和常见判例","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"网球规则 · 适用范围与版本说明至七、抢十与无占先：先看规程再记分","link":"/life/personal/sports/tennis-rules-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"网球规则 · 适用范围与版本说明至七、抢十与无占先：先看规程再记分","link":"/life/personal/sports/tennis-rules-part-01"},"next":false},"headers":[],"relativePath":"life/personal/sports/tennis-rules-part-02.md","filePath":"life/personal/sports/tennis-rules-part-02.md"}'),l={name:"life/personal/sports/tennis-rules-part-02.md"};function i(s,e,o,d,p,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="网球规则-·-八、用三个场景把比分读完整至官方来源与复核入口" tabindex="-1">网球规则 · 八、用三个场景把比分读完整至官方来源与复核入口 <a class="header-anchor" href="#网球规则-·-八、用三个场景把比分读完整至官方来源与复核入口" aria-label="Permalink to &quot;网球规则 · 八、用三个场景把比分读完整至官方来源与复核入口&quot;">​</a></h1><p><a href="/life/personal/sports/tennis-rules">返回分篇目录</a></p><p>网球先争每一分，再由分组成局、由局组成盘，最后按盘数决定胜负。入门最容易混淆的不是击球动作，而是发球顺序、40 平后的计分，以及不同赛事采用的决胜办法。</p><h2 id="八、用三个场景把比分读完整" tabindex="-1">八、用三个场景把比分读完整 <a class="header-anchor" href="#八、用三个场景把比分读完整" aria-label="Permalink to &quot;八、用三个场景把比分读完整 {#八、用三个场景把比分读完整}&quot;">​</a></h2><ol><li><strong>普通局 40 平，发球方先得分。</strong> 发球方占先；下一分接发方赢，又回到 40 平；发球方随后连赢两分才拿下本局。不要把“至少四分”简化成任何时候赢第四分都结束，也不要把这一流程套到无占先制。</li><li><strong>一发出界，二发擦网后落入正确发球区。</strong> 判二发重发；接下来这一发若出界，就是双误，接发方得分。擦网重发并没有把之前的一发失误取消。</li><li><strong>抢七 6∶6，A 赢下一分到 7∶6。</strong> 尚未领先两分，继续比赛；若 A 再赢为 8∶6，拿下抢七，也以 7∶6 的局分赢下这盘。一个是抢七的小分，一个是本盘局分，不能把 8∶6 写成这盘的局数。</li></ol><h2 id="九、第一次比赛与观赛的顺序" tabindex="-1">九、第一次比赛与观赛的顺序 <a class="header-anchor" href="#九、第一次比赛与观赛的顺序" aria-label="Permalink to &quot;九、第一次比赛与观赛的顺序 {#九、第一次比赛与观赛的顺序}&quot;">​</a></h2><p>赛前先确认“几盘几胜、6∶6 怎么办、决胜盘怎么办、是否无占先”；再抽签决定发接球或选边。普通局由同一人发整局，每分右、左交替；下一局换对方发球。每局结束先记局数，检查是否换边和是否进入抢七，盘结束再更新盘数。</p><p>观赛时，可以先关注发球落在哪个区、接发后双方站在底线还是来到网前，再看这一分如何结束。底线相持常在争取角度和时间；上网球员希望在较靠前的位置处理来球。这些是战术倾向，不是必须遵循的站位。双打同伴可以协同移动，但本盘的发球、接发次序不能因战术临时改变。</p><table tabindex="0"><thead><tr><th>术语</th><th>入门解释</th></tr></thead><tbody><tr><td>Ace</td><td>合法发球直接得分，接发方未触及球</td></tr><tr><td>双误</td><td>同一分两次发球均失误，接发方得分；合法重发不算一次失误</td></tr><tr><td>破发</td><td>接发方赢下对方的发球局，不是接到一记强力发球</td></tr><tr><td>破发点</td><td>接发方再赢这一分就能赢局的比分状态</td></tr><tr><td>截击</td><td>球未落地前击球；不能用于接发球</td></tr><tr><td>Deuce／Advantage</td><td>普通占先局的平分／占先状态</td></tr><tr><td>Tie-break／Match tie-break</td><td>抢七等决胜局／替代决胜盘的比赛决胜局，目标小分与触发条件要查规程</td></tr></tbody></table><p>双打回合中无需像乒乓球那样每拍交替击球。同一人可以连续处理本队不同次来球；但不能由两名同伴各碰一下，把同一个球接力送过网。</p><h2 id="十、快速自测" tabindex="-1">十、快速自测 <a class="header-anchor" href="#十、快速自测" aria-label="Permalink to &quot;十、快速自测 {#十、快速自测}&quot;">​</a></h2><ol><li>双打一发落在双打边道内、发球线之前，算好球吗？</li><li>第二发擦网后落入正确发球区，下一球是一发还是二发？</li><li>抢七 6∶5 时领先者再赢一分，是否结束？</li><li>抢七第一分 A 发球，第 4 分轮到谁发？</li><li>双打接发球员本盘一直接右区，能因对手发球强临时换成接左区吗？</li></ol><p><strong>答案：</strong> ①不算，双打发球区不包括边道。②标准规则下仍是二发。③结束，7∶5 已至少 7 分且领先 2 分。④A，从左区发。⑤不能随意改变本盘接发顺序；下一盘可以重新决定。</p><h2 id="官方来源与复核入口" tabindex="-1">官方来源与复核入口 <a class="header-anchor" href="#官方来源与复核入口" aria-label="Permalink to &quot;官方来源与复核入口 {#官方来源与复核入口}&quot;">​</a></h2><ul><li><a href="https://www.itftennis.com/en/about-us/governance/rules-and-regulations/" target="_blank" rel="noopener noreferrer">ITF：Rules and Regulations</a>：查找当年度《Rules of Tennis》及附录。</li><li><a href="https://www.itftennis.com/media/7221/2026-rules-of-tennis-english.pdf" target="_blank" rel="noopener noreferrer">2026 Rules of Tennis 英文正文</a>：第 1 条及 Appendix IX 查场地图；第 5—7 条查比分；第 16—23 条查发球；Appendix VI 查可选计分办法。</li><li>重点查阅规则第 1 条“场地”、第 5～7 条“局、盘、场计分”、第 9～23 条中的发接球顺序、发球失误与重发规定、第 24～26 条“失分、合法回球和妨碍”，以及“Alternative Procedures and Scoring Methods”附录。</li></ul><p>本次已读取 2026 官方规则正文，核对场地、计分及发球的主要条款；本文并非全部条文的逐条翻译，特殊赛制仍以当年正式规则及比赛规程为准。</p>',16)])])}const f=t(l,[["render",i]]);export{h as __pageData,f as default};
